package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.text.Spanned;import android.text.style.ForegroundColorSpan;import java.io.*;import java.util.concurrent.atomic.*;

public class ReadingFollowTest extends Instrumentation {
    void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}
    void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier predicate,String message,long timeout)throws Exception{long until=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<until){AtomicBoolean ready=new AtomicBoolean();ui(()->ready.set(predicate.getAsBoolean()));if(ready.get())return;Thread.sleep(50);}throw new AssertionError(message);}
    void drag(MainActivity a){long now=SystemClock.uptimeMillis();float x=a.scroll.getWidth()/2f,y=a.scroll.getHeight()*.8f;int[] actions={MotionEvent.ACTION_DOWN,MotionEvent.ACTION_MOVE,MotionEvent.ACTION_MOVE,MotionEvent.ACTION_UP};for(int i=0;i<actions.length;i++){MotionEvent event=MotionEvent.obtain(now,now+i*180,actions[i],x,y-i*a.scroll.getHeight()*.18f,0);a.scroll.dispatchTouchEvent(event);event.recycle();}}
    public void onCreate(Bundle state){super.onCreate(state);start();}
    public void onStart(){Bundle result=new Bundle();MainActivity activity=null;Context context=getTargetContext();android.content.SharedPreferences voicePrefs=context.getSharedPreferences("reading_settings",0);String voicePreference=MainActivity.readingVoicePreference(VoiceLanguages.systemLanguage(context));boolean hadPreference=voicePrefs.contains(voicePreference);String oldPreference=voicePrefs.getString(voicePreference,"");boolean passed=false;try{
        check(!context.getSystemService(KeyguardManager.class).isKeyguardLocked(),"Unlock phone for scrolling test");activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","reading_follow_qa").putExtra("book_name","滚动跟随验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.system!=null&&a.system.initialized&&a.system.offlineVoice("zh","")!=null,"system Chinese voice not ready",40000);ui(()->{StringBuilder book=new StringBuilder();for(int chapter=1;chapter<=2;chapter++){book.append("第").append(chapter).append("章 山间的风\n");for(int i=0;i<140;i++)book.append("微风轻轻吹过山间，书页慢慢翻动。我们沿着小路前行，欣赏四周的风景。\n");}a.text=book.toString();a.chapters=MainActivity.parse(a.text);check(a.chapters.size()==2,"fixture split");a.position=0;a.readingLanguage="";a.loopPlayback=false;a.rate=1;a.systemVoiceKey=a.system.offlineVoice("zh","").key;voicePrefs.edit().putString(voicePreference,a.systemVoiceKey).commit();a.showPosition(true);a.startReading();});await(()->a.playing&&a.focusGeneration==a.generation&&a.latestStatus.startsWith(a.getString(R.string.ui_74)),"actual speech not started",30000);
        AtomicInteger first=new AtomicInteger();ui(()->{first.set(a.position);for(int gesture=0;gesture<4;gesture++)drag(a);check(a.readingFollow.resumeAt>SystemClock.elapsedRealtime(),"manual scrolling did not suspend follow");});await(()->a.scroll.getScrollY()>a.dp(100),"body did not scroll",3000);Thread.sleep(1400);AtomicInteger browsed=new AtomicInteger();AtomicLong deadline=new AtomicLong(),updates=new AtomicLong();ui(()->{browsed.set(a.scroll.getScrollY());deadline.set(a.readingFollow.resumeAt);updates.set(a.highlightUpdates);});
        Thread.sleep(2300);ui(()->{check(a.scroll.getScrollY()>=browsed.get()-a.dp(5),"speech pulled view backward during browsing");check(a.position>first.get()&&a.highlightUpdates>updates.get(),"speech or highlight paused during browsing");Spanned text=(Spanned)a.content.getText();check(text.getSpans(0,text.length(),ForegroundColorSpan.class).length>0,"highlight missing while browsing");long old=a.readingFollow.resumeAt;a.scroll.scrollBy(0,a.dp(30));check(a.readingFollow.resumeAt>=old,"inertial movement failed to extend delay");deadline.set(a.readingFollow.resumeAt);browsed.set(a.scroll.getScrollY());});
        await(()->a.readingFollow.remaining(SystemClock.elapsedRealtime())<700,"ten-second wait did not expire",14000);ui(()->{check(a.readingFollowBlocked(),"follow resumed before ten seconds");check(a.scroll.getScrollY()>=browsed.get()-a.dp(5),"early return before last manual scroll + ten seconds");});await(()->a.readingFollow.resumeAt==0&&a.scroll.getScrollY()<browsed.get()-a.dp(50),"did not resume at latest spoken location",3500);ui(()->{check(a.playing,"auto-follow stopped playback");check(!a.scroll.manualMotion,"programmatic follow left manual tracking enabled");});Thread.sleep(500);ui(()->check(a.readingFollow.resumeAt==0,"automatic scroll restarted the delay"));
        ui(()->{a.scroll.manualMotion=true;a.scroll.scrollTo(0,a.dp(700));a.manualReadingMovement();int visible=a.renderedChapter;a.position=a.chapters.get(1).start;a.showPosition(false);a.highlight(a.position,a.position+10);check(a.chapter==1&&a.renderedChapter==visible,"chapter transition replaced browsed text");a.readingFollow.resumeAt=SystemClock.elapsedRealtime();a.resumeReadingFollow();check(a.renderedChapter==1,"resume did not render current playing chapter");});waitForIdleSync();Thread.sleep(400);
        ui(()->{a.manualReadingMovement();a.jump(0);check(a.readingFollow.resumeAt==0&&a.chapter==0,"explicit chapter navigation did not reset follow");});await(()->a.playing&&a.focusGeneration==a.generation&&a.latestStatus.startsWith(a.getString(R.string.ui_74)),"chapter navigation did not resume speech",15000);ui(()->{a.stop();a.scroll.manualMotion=true;a.scroll.scrollTo(0,a.dp(600));int y=a.scroll.getScrollY();a.readingFollow.resumeAt=SystemClock.elapsedRealtime()-1;a.resumeReadingFollow();check(a.scroll.getScrollY()==y,"paused player unexpectedly repositioned text");});result.putString("result","PASS: actual manual drag and inertial updates; uninterrupted speech/highlight; no relocation before last scroll +10 seconds; automatic return to latest reading position; automatic scroll does not rearm timeout; defer automatic chapter rendering during browsing; explicit chapter navigation resumes follow; paused player stays put");passed=true;
    }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));if(activity!=null){final MainActivity a=activity;ui(()->result.putString("state","playing="+a.playing+" position="+a.position+" scroll="+a.scroll.getScrollY()+" remaining="+a.readingFollow.remaining(SystemClock.elapsedRealtime())+" touching="+a.scroll.touching));}}finally{if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}android.content.SharedPreferences.Editor voiceEdit=voicePrefs.edit();if(hadPreference)voiceEdit.putString(voicePreference,oldPreference);else voiceEdit.remove(voicePreference);voiceEdit.commit();context.getSharedPreferences("reader_reading_follow_qa",0).edit().clear().commit();new File(context.getFilesDir(),"book_reading_follow_qa.txt.position").delete();}finish(passed?-1:0,result);}
}
